                tool_calls.append(
                    chat_schema.ToolCallDelta(
                        index=0,
                        id=call_id,
                        function=Function(
                            name=func_name,
                            arguments=func_arguments,
                        ),
                        type="function",
                        thought_signature=thought_sig,
                    )
                )
            else:
                tool_calls.append(
                    ToolCall(
                        id=call_id,
                        function=Function(
                            name=func_name,
                            arguments=func_arguments,
                        ),
                        type="function",
                        thought_signature=thought_sig,
                    )
                )
