@pytest.mark.parametrize("provider_name", ["gemini", "vertex_ai"])
@pytest.mark.parametrize("stream", [False, True])
@pytest.mark.parametrize("tools", ["omitted", "empty", "declared"])
@pytest.mark.parametrize(
    ("tool_choice", "expected_config"),
    [
        (None, None),
        ("auto", None),
        ("required", {"mode": "ANY"}),
        ("none", {"mode": "NONE"}),
        (
            {"type": "function", "function": {"name": "get_weather"}},
            {"mode": "ANY", "allowedFunctionNames": ["get_weather"]},
        ),
    ],
)
@pytest.mark.asyncio
async def test_gemini_tool_choice(provider_name, stream, tools, tool_choice, expected_config):
    config = chat_config()
    if provider_name == "vertex_ai":
        config["model"]["provider"] = "vertex_ai"
        config["model"]["config"] = {"vertex_project": "test-project"}
        provider = VertexAIProvider(EndpointConfig(**config))
        provider._cached_credentials = mock.Mock(token="test-token", valid=True)
    else:
        provider = GeminiProvider(EndpointConfig(**config))

    payload = chat_function_calling_payload(stream=stream)
    if tools == "omitted":
        payload.pop("tools")
    elif tools == "empty":
        payload["tools"] = []
    else:
        payload["tools"].append({
            "type": "function",
            "function": {
                "name": "get_time",
                "description": "Get the current time.",
                "parameters": {"type": "object", "properties": {}},
            },
        })
    if tool_choice is not None:
        payload["tool_choice"] = tool_choice

    response = (
        MockAsyncStreamingResponse(chat_stream_response())
        if stream
        else MockAsyncResponse(fake_chat_response())
    )
    with mock.patch("aiohttp.ClientSession.post", return_value=response) as mock_post:
        if stream:
            chunks = [chunk async for chunk in provider.chat_stream(chat.RequestPayload(**payload))]
            assert chunks
        else:
            await provider.chat(chat.RequestPayload(**payload))

    mock_post.assert_called_once()
    body = mock_post.call_args.kwargs["json"]
    if tools == "declared" and expected_config is not None:
        assert body["toolConfig"] == {"functionCallingConfig": expected_config}
    else:
        assert "toolConfig" not in body
    if tools == "declared":
        assert [f["name"] for f in body["tools"][0]["functionDeclarations"]] == [
            "get_weather",
            "get_time",
        ]
    else:
        assert "tools" not in body


